package org.sleepwell.app;
import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Retained bounded document work. Cancellation closes providers off-main; merge never schedules timers. */
final class NapProfilesDocumentsJob {
 enum Phase {IDLE,PREPARING,EXPORT_READY,CHOOSING,READING,REVIEWING,REVIEW,WRITING,MERGING,CLOSING,BLOCKED,DONE,ERROR}
 enum Kind {EXPORT,IMPORT}
 static final class State {final Phase phase;final String message;final NapProfilesDefinitions.Plan plan;final int count;final boolean busy;State(Phase p,String m,NapProfilesDefinitions.Plan plan,int count,boolean busy){phase=p;message=m;this.plan=plan;this.count=count;this.busy=busy;}}
 private static NapProfilesDocumentsJob singleton;static synchronized NapProfilesDocumentsJob get(Context context){if(singleton==null)singleton=new NapProfilesDocumentsJob(context.getApplicationContext());return singleton;}
 final String id=UUID.randomUUID().toString();final Context app;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final AtomicBoolean occupied=new AtomicBoolean(),cancelled=new AtomicBoolean();private final Handler main=new Handler(Looper.getMainLooper());private volatile NativeTransport transport;private volatile byte[] prepared;private volatile List<NapProfilesDefinitions.Definition> incoming;private volatile State state=new State(Phase.IDLE,"",null,0,false);private String ticket="";private Kind choosing;private long generation;
 private NapProfilesDocumentsJob(Context app){this.app=app;}State state(){return state;}
 private interface Work {State run()throws Exception;}
 private boolean begin(Phase phase,Work operation){if(!occupied.compareAndSet(false,true))return false;cancelled.set(false);long mine=++generation;state=new State(phase,"",state.plan,state.count,true);main.postDelayed(()->{if(generation==mine&&occupied.get()&&state.phase!=Phase.MERGING&&state.phase!=Phase.BLOCKED)cancel("Document provider timed out. Stopping provider work…");},45000);try{worker.execute(()->{State result;try{result=operation.run();if(cancelled.get())throw new InterruptedIOException("Operation cancelled. An export document may be empty or partial.");}catch(Exception failure){String message=failure.getMessage()==null?"Profile document operation failed. Choose the document again.":failure.getMessage();if(message.length()>280)message=message.substring(0,280);result=new State(incoming!=null&&state.plan!=null?Phase.REVIEW:Phase.ERROR,message,state.plan,state.count,false);}NativeTransport owned=transport;boolean closed=true;if(owned!=null)try{owned.finish();}catch(IOException failure){closed=false;}if(!closed){state=new State(Phase.BLOCKED,"Document cleanup is not confirmed. Retry cleanup before another operation.",result.plan,result.count,true);return;}transport=null;state=result;occupied.set(false);});return true;}catch(RuntimeException rejected){state=new State(Phase.ERROR,"Document worker could not start.",state.plan,state.count,false);occupied.set(false);return false;}}
 boolean prepare(){if(state.phase==Phase.CHOOSING)return false;return begin(Phase.PREPARING,()->{active();List<NapProfiles.Profile> profiles=new NapProfilesStore(app).read().profiles;byte[] bytes=NapProfilesDefinitions.encode(profiles);active();prepared=bytes;incoming=null;return new State(Phase.EXPORT_READY,"Definitions prepared. Choose a destination for this copy.",null,profiles.size(),false);});}
 synchronized String choose(Kind kind){if(occupied.get()||state.phase==Phase.CHOOSING||kind==Kind.EXPORT&&(prepared==null||state.phase!=Phase.EXPORT_READY))return "";choosing=kind;ticket=UUID.randomUUID().toString();if(kind==Kind.IMPORT){incoming=null;prepared=null;}state=new State(Phase.CHOOSING,"Choose a profile document.",null,state.count,false);return ticket;}
 synchronized void choiceCancelled(String expected){if(!ticket.equals(expected)||state.phase!=Phase.CHOOSING)return;ticket="";state=new State(choosing==Kind.EXPORT&&prepared!=null?Phase.EXPORT_READY:Phase.IDLE,"Document selection cancelled. No definitions changed.",null,state.count,false);}
 synchronized void choiceFailed(String expected){if(!ticket.equals(expected)||state.phase!=Phase.CHOOSING)return;choiceCancelled(expected);state=new State(Phase.ERROR,"A document provider could not open. Try again.",null,0,false);}
 synchronized boolean document(String expected,Uri uri){if(!ticket.equals(expected)||state.phase!=Phase.CHOOSING||uri==null||!"content".equals(uri.getScheme())||uri.getAuthority()==null)return false;Kind kind=choosing;ticket="";String chosen=uri.toString();if(kind==Kind.EXPORT){byte[] copy=prepared;if(copy==null)return false;return begin(Phase.WRITING,()->{NativeTransport io=new NativeTransport(app,()->cancelled.get());transport=io;active();try(OutputStream out=io.output(chosen)){for(int at=0;at<copy.length;at+=4096){active();out.write(copy,at,Math.min(4096,copy.length-at));}active();out.flush();}active();prepared=null;return new State(Phase.DONE,"Profile definitions exported. Timers and application ownership were excluded.",null,state.count,false);});}return begin(Phase.READING,()->{NativeTransport io=new NativeTransport(app,()->cancelled.get());transport=io;byte[] bytes;try(InputStream input=io.input(chosen)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[4096];int empty=0;while(true){active();int count=input.read(block);if(count<0)break;if(count==0){if(++empty>16)throw new IOException("Document provider returned no data.");continue;}empty=0;if(count>NapProfilesDefinitions.LIMIT-out.size())throw new IOException("Profile documents must be no larger than 64 KiB.");out.write(block,0,count);}bytes=out.toByteArray();}active();List<NapProfilesDefinitions.Definition> definitions=NapProfilesDefinitions.decode(bytes);active();NapProfilesDefinitions.Plan plan=new NapProfilesDefinitions.Plan(definitions,new NapProfilesStore(app).read().profiles);incoming=definitions;return new State(Phase.REVIEW,"Review this merge. No timers will start.",plan,definitions.size(),false);});}
 boolean refresh(){List<NapProfilesDefinitions.Definition> definitions=incoming;if(definitions==null||state.plan==null)return false;return begin(Phase.REVIEWING,()->new State(Phase.REVIEW,"Import review refreshed. Confirm the merge again.",new NapProfilesDefinitions.Plan(definitions,new NapProfilesStore(app).read().profiles),definitions.size(),false));}
 boolean merge(){State reviewed=state;if(reviewed.phase!=Phase.REVIEW||reviewed.plan==null||!reviewed.plan.fits()||reviewed.plan.additions.isEmpty())return false;return begin(Phase.MERGING,()->{int count=new NapProfilesStore(app).mergeDefinitions(reviewed.plan);incoming=null;prepared=null;return new State(Phase.DONE,count+" new profile definition"+(count==1?"":"s")+" merged. Existing definitions and all timers are unchanged.",null,count,false);});}
 void cancel(String reason){if(!occupied.get()||state.phase==Phase.MERGING||state.phase==Phase.BLOCKED)return;cancelled.set(true);state=new State(Phase.CLOSING,reason,state.plan,state.count,true);NativeTransport io=transport;if(io!=null)io.cancel();}
 void retryCleanup(){if(state.phase!=Phase.BLOCKED||transport==null)return;NativeTransport retained=transport;state=new State(Phase.CLOSING,"Retrying document cleanup…",state.plan,state.count,true);try{worker.execute(()->{try{retained.finish();transport=null;state=new State(Phase.ERROR,"Document closed. Choose a document again before continuing.",null,0,false);occupied.set(false);}catch(IOException failure){state=new State(Phase.BLOCKED,"Document cleanup is still unconfirmed. Retry later.",state.plan,state.count,true);}});}catch(RuntimeException failure){state=new State(Phase.BLOCKED,"Cleanup worker is unavailable. Document ownership remains blocked.",state.plan,state.count,true);}}
 void discardReview(){if(occupied.get()||state.phase==Phase.CHOOSING)return;incoming=null;prepared=null;state=new State(Phase.IDLE,"Review discarded. No definitions or timers changed.",null,0,false);}
 private void active()throws IOException{if(cancelled.get())throw new InterruptedIOException("Operation cancelled. An export document may be empty or partial.");}
 private static final class NativeTransport {private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->{Thread t=new Thread(r,"nap-profile-document-close");t.setDaemon(true);return t;},new ThreadPoolExecutor.DiscardPolicy());final ContentResolver resolver;final java.util.function.BooleanSupplier cancelled;final AtomicReference<CancellationSignal> signal=new AtomicReference<>();final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();NativeTransport(Context app,java.util.function.BooleanSupplier cancelled){resolver=app.getContentResolver();this.cancelled=cancelled;}ParcelFileDescriptor open(String uri,String mode)throws IOException{CancellationSignal pending=new CancellationSignal();signal.set(pending);if(cancelled.getAsBoolean())throw new InterruptedIOException("Document operation cancelled.");ParcelFileDescriptor file=resolver.openFileDescriptor(Uri.parse(uri),mode,pending);if(file==null)throw new IOException("Document is unavailable.");descriptor.set(file);if(cancelled.getAsBoolean()){finish();throw new InterruptedIOException("Document operation cancelled.");}return file;}InputStream input(String uri)throws IOException{return new ParcelFileDescriptor.AutoCloseInputStream(open(uri,"r"));}OutputStream output(String uri)throws IOException{return new ParcelFileDescriptor.AutoCloseOutputStream(open(uri,"wt"));}void finish()throws IOException{ParcelFileDescriptor file=descriptor.get();if(file!=null){file.close();descriptor.compareAndSet(file,null);}signal.set(null);}void cancel(){CancellationSignal pending=signal.get();CANCEL.execute(()->{try{if(pending!=null)pending.cancel();}finally{try{finish();}catch(IOException ignored){}}});}}
}
